                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; Create Or Replace table datalake_db.kaya.dwh_Kaya_D2C_PandL as select Null as customer_id ,coalesce(pre_marketplace,Marketplace_sp) shop_name ,coalesce(pre_marketplace,Marketplace_sp) marektplace ,(final_utm_channel) AS CHANNEL ,(final_utm_source) AS SOURCE ,(final_utm_platform_traffic) as PLATFORM_TRAFFIC ,final_utm_branding ,b.ORDER_ID ,reference_code ,phone as PHONE ,name as NAME ,email as EMAIL ,shipping_last_update_date AS SHIPPING_LAST_UPDATE_DATE ,SKU ,b.PRODUCT_ID ,coalesce(p2.PRODUCT_NAME,b.PRODUCT_NAME) AS PRODUCT_NAME ,CURRENCY ,upper(CITY) as city ,upper(STATE) AS State ,upper(ORDER_STATUS) order_status ,coalesce(ms.Date,b.order_date)::date AS Order_Date ,order_date as ORDER_TIMESTAMP ,SUBORDER_QUANTITY AS QUANTITY ,ifnull(SELLING_PRICE,0) - ifnull(tax,0) gross_sales_before_tax ,case when MRP_SALES is null or MRP_SALES = 0 then b.DISCOUNT else (MRP_SALES - b.SELLING_PRICE) end AS DISCOUNT ,TAX ,SHIPPING_PRICE ,SELLING_PRICE AS SELLING_PRICE ,ifnull(MRP_SALES,0) as MRP_SALES ,upper(ORDER_STATUS) as OMS_ORDER_STATUS ,upper(coalesce(b.shippingpackagestatus,b.shipping_status)) AS SHIPPING_STATUS ,upper(coalesce(b.shippingpackagestatus,b.shipping_status)) FINAL_SHIPPING_STATUS ,saleOrderItemCode as SALEORDERITEMCODE ,SALES_ORDER_ITEM_ID as SALES_ORDER_ITEM_ID ,AWB ,null as payment_gateway ,upper(payment_mode) payment_mode ,upper(coalesce(COURIER, courier_aggregator)) COURIER ,DISPATCH_DATE AS DISPATCH_DATE ,delivered_date as delivered_date ,case when upper(FINAL_SHIPPING_STATUS) in (\'DELIVERED\') then 1 end AS DELIVERED_STATUS ,return_flag AS RETURN_FLAG ,case when return_flag = 1 then suborder_quantity::int end returned_quantity ,case when return_flag = 1 then selling_price::float end returned_sales ,case when return_flag = 0 and lower(order_status) in (\'cancelled\') then suborder_quantity::int end cancelled_quantity ,new_customer_flag::varchar as NEW_CUSTOMER_FLAG ,NULL as ACQUISITION_PRODUCT ,case when order_status=\'COMPLETE\' then delivered_date::date-order_date::date else current_date - order_date::Date end as days_in_shipment ,NULL AS ACQUSITION_DATE ,b.commonsku sku_code ,upper(coalesce(SUB_CATEGORY,b.Product_Category)) PRODUCT_CATEGORY ,upper(b.product_sub_category) PRODUCT_SUB_CATEGORY ,null as brand ,upper(warehouse_name) warehouse ,pincode ,courierstatus ,selling_price line_item_sales ,null refund_amount_without_lineitem ,null as discount_code ,Cogs ,current_date as current_date_field ,div0(ifnull(TR.Targets,0) , count(*) over(partition by last_day(b.order_date),lower(b.pre_marketplace))) Targets ,div0(ifnull(TR.Spend_Targets,0) , count(*) over(partition by last_day(b.order_date),lower(b.pre_marketplace))) Spend_Targets ,div0(ifnull(TR.NR_Targets,0) , count(*) over(partition by last_day(b.order_date),lower(b.pre_marketplace))) NR_Targets ,div0(ifnull(ms.spend,0) , count(*) over(partition by coalesce(ms.Date,b.order_date::date),lower(coalesce(b.pre_marketplace,Marketplace_sp)))) Spend from ( Select *, upper(case when marketplace = \'KAYASCIENCE_SHOPIFY\' then \'KAYASCIENCE_D2C_P&L\' else marketplace end) pre_marketplace from datalake_db.kaya.dwh_unicommerce_fact_items where (courierstatus = \'DELIVERED\' and marketplace = \'KAYASCIENCE_SHOPIFY\' and not(lower(replace(product_name,\' \',\'\')) in (select distinct lower(replace(\"SKU Name\",\' \',\'\')) from datalake_db.kaya.kaya_db_product_names_to_exclude))) )b left join ( select order_id, final_utm_source, final_utm_channel, final_utm_platform_traffic, final_utm_branding from datalake_db.kaya.dwh_SHOPIFY_FACT_ITEMS qualify row_number() over(partition by order_id order by 1) = 1 )so on b.order_id = so.order_id left join ( select * from datalake_db.kaya.Final_SKU_master qualify row_number() over(partition by trim(upper(marketplace_sku)) order by 1) = 1 )p2 on trim(upper(b.sku)) = upper(trim(p2.marketplace_sku)) left join ( select upper(variant_sku) variant_sku ,replace(replace(cogs,\',\',\'\'),\'NA\',0)::float as Cogs from datalake_db.kaya.kaya_db_sku_mrp_cogs )smc on lower(b.sku) = lower(smc.variant_sku) left join ( SELECT LAST_DAY(TO_DATE(month, \'YYYY-MM-DD\')) AS Month, CAST(REPLACE(REPLACE(GMV, \'NA\', \'0\'), \',\', \'\') AS FLOAT) AS Targets, CAST(REPLACE(REPLACE(SPEND, \'NA\', \'0\'), \',\', \'\') AS FLOAT) AS Spend_Targets, CAST(REPLACE(REPLACE(NR, \'NA\', \'0\'), \',\', \'\') AS FLOAT) AS NR_Targets, \'KAYASCIENCE_D2C_P&L\' AS Marketplace_t FROM datalake_db.kaya.trn_dtc_monthly_targets )TR on last_day(b.order_date) = tr.month and lower(b.pre_marketplace) = lower(tr.Marketplace_t) full outer join ( select Date ,\'KAYASCIENCE_D2C_P&L\' as Marketplace_sp ,sum(ifnull(spend,0)) spend from Datalake_db.kaya.DWH_KAYA_MARKETING_CONSOLIDATED where lower(account_name) like \'%shopify%\' and not(lower(ifnull(campaign_name,\'\')) like \'%branding%\') group by 1,2 ) ms on ms.Date = b.order_date::date and lower(ms.Marketplace_sp) = lower(b.pre_marketplace) ;",
                    "transaction": true
